// Calculate weekly summary for this student
// Get student info from the registry loop
const registryItem = $('Loop Over Each Student').first().json;
const studentName = registryItem['student_name'] || 'Student';
const chatId = String(registryItem['telegram_chat_id']);

// All rows for this student
const allRows = $input.all().map(r => r.json);

// Filter to last 7 days in IST
const istOffset = 5.5 * 60 * 60 * 1000;
const now = new Date();
const todayIST = new Date(now.getTime() + istOffset);

// Build last 7 day strings DD/MM/YYYY
const last7 = [];
for (let i = 6; i >= 0; i--) {
  const d = new Date(todayIST);
  d.setUTCDate(d.getUTCDate() - i);
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const yyyy = d.getUTCFullYear();
  last7.push(`${dd}/${mm}/${yyyy}`);
}

const weekStart = last7[0];
const weekEnd = last7[6];

// Filter rows to last 7 days
const weekRows = allRows.filter(r => last7.includes(r['Date']));

// Sum Hours Target (weekly target)
const weeklyTarget = weekRows.reduce((sum, r) => {
  const h = parseFloat(r['Hours Target']);
  return sum + (isNaN(h) ? 0 : h);
}, 0);

// Sum Actual Hours
const weeklyActual = weekRows.reduce((sum, r) => {
  const h = parseFloat(r['Actual Hours']);
  return sum + (isNaN(h) ? 0 : h);
}, 0);

// Count days where Completion Status is not empty
const daysCompleted = weekRows.filter(r => r['Completion Status'] && r['Completion Status'].trim() !== '').length;

// Avg Productivity
const prodValues = weekRows
  .map(r => parseFloat(r['Productivity']))
  .filter(v => !isNaN(v));
const avgProd = prodValues.length > 0
  ? (prodValues.reduce((a, b) => a + b, 0) / prodValues.length).toFixed(1)
  : '—';

// Percentage achieved
const pct = weeklyTarget > 0 ? (weeklyActual / weeklyTarget) * 100 : 0;

// Pick closing line
let closing = '';
if (pct >= 90) closing = '🏆 Outstanding week! You\'re on fire. Keep this consistency.';
else if (pct >= 75) closing = '💪 Great consistency this week! Keep it up.';
else if (pct >= 50) closing = '⚠️ Decent effort, but there\'s room to improve. Let\'s push harder next week.';
else closing = '🙏 Tough week. That\'s okay. Every week is a fresh start. Come back stronger.';

// Format week range label
const parseDate = str => {
  const [d, m, y] = str.split('/');
  return new Date(y, m - 1, d).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
};
const weekLabel = `${parseDate(weekStart)} – ${parseDate(weekEnd)}`;

return [{
  json: {
    chat_id: chatId,
    student_name: studentName,
    week_label: weekLabel,
    total_hours: weeklyActual.toFixed(1),
    target_hours: weeklyTarget.toFixed(0),
    days_completed: daysCompleted,
    avg_productivity: avgProd,
    closing_line: closing
  }
}];

